template <typename Target>
inline flight::Ref<GlViewportRect> resolve_gl_pass_viewport(
    const std::shared_ptr<Target>& target,
    std::optional<flight::Ref<Viewport>> viewport) {
  if (!viewport.has_value()) {
    return flight::make_ref<GlViewportRect>(GlViewportRect{
        .height = target->height, .width = target->width, .x = 0.0, .y = 0.0});
  }
  const double pass_width = flight::maximum(0.0, viewport.value()->width);
  const double pass_height = flight::maximum(0.0, viewport.value()->height);
  const double raw_left = std::floor(viewport.value()->x);
  const double raw_right = pass_width == 0.0
      ? raw_left : std::ceil(viewport.value()->x + pass_width);
  const double raw_top = std::floor(viewport.value()->y);
  const double raw_bottom = pass_height == 0.0
      ? raw_top : std::ceil(viewport.value()->y + pass_height);
  const double left = clamp_gl_pass_edge(raw_left, target->width);
  const double right = clamp_gl_pass_edge(raw_right, target->width);
  const double top = clamp_gl_pass_edge(raw_top, target->height);
  const double bottom = clamp_gl_pass_edge(raw_bottom, target->height);
  return flight::make_ref<GlViewportRect>(GlViewportRect{
      .height = flight::maximum(0.0, bottom - top),
      .width = flight::maximum(0.0, right - left),
      .x = left, .y = target->height - bottom});
}



