  runtime->current_framebuffer = framebuffer;
  runtime->current_render_target = GlRenderTargetVariant{
      std::in_place_type<flight::Ref<GlRenderTarget>>, target_view};
  runtime->render_target_viewport = active_viewport;
  runtime->current_scissor_rect = active_scissor.has_value()
      ? std::variant<flight::Ref<GlScissorRect>, flight::Null,
                     flight::Undefined>{std::in_place_type<flight::Ref<GlScissorRect>>,
                                        active_scissor.value()}
      : std::variant<flight::Ref<GlScissorRect>, flight::Null,
                     flight::Undefined>{std::in_place_type<flight::Null>, flight::null};
  runtime->scissor_stack = active_scissor.has_value()
      ? flight::Array<flight::Ref<GlScissorRect>>{active_scissor.value()}
      : flight::Array<flight::Ref<GlScissorRect>>{};
