  if (previous_owner != state) invalidate_gl_pass_binding_cache(previous_runtime);
  clear_gl_render_pass(state, target, clear);

  const auto pass = acquire_gl_render_pass_handle(gl, state, target);
  runtime->current_pass = pass;
